import{_ as s,c as n,o as e,a0 as t}from"./chunks/framework.C1J0Vcxi.js";const h=JSON.parse('{"title":"架构概览","description":"","frontmatter":{"title":"架构概览","date":"2026-05-09T00:00:00.000Z","type":"description"},"headers":[],"relativePath":"docs/architecture.md","filePath":"docs/architecture.md"}'),p={name:"docs/architecture.md"};function r(i,a,c,o,l,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h1><p>RT-Async 是一个基于 Rust 的 <code>#![no_std]</code> async RTOS 内核，采用优先级抢占 + 同优先级协程协作的混合调度模型。</p><h2 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h2><h3 id="executor-线程" tabindex="-1">Executor = 线程 <a class="header-anchor" href="#executor-线程" aria-label="Permalink to &quot;Executor = 线程&quot;">​</a></h3><p>系统中每个 <strong>executor</strong> 绑定一个固定优先级，概念上就是一个独立的调度线程。executor 之间通过抢占切换，executor 内部多个任务通过 <code>.await</code> 协作让权。</p><h3 id="共享系统栈" tabindex="-1">共享系统栈 <a class="header-anchor" href="#共享系统栈" aria-label="Permalink to &quot;共享系统栈&quot;">​</a></h3><p>所有 executor 共用同一个系统栈。高优先级 executor 抢占低优先级时，直接在当前栈上继续压栈运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────┐  ← SP 初始位置</span></span>
<span class="line"><span>│                              │</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│  Executor C (prio 0, 最高)   │  ← 抢占 B，SP 继续上移</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│  Executor B (prio 2)         │  ← 抢占 A，SP 继续上移</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│  Executor A (prio 5, 最低)   │  ← 当前运行的 executor</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│  空闲                        │</span></span>
<span class="line"><span>└──────────────────────────────┘</span></span></code></pre></div><p>高优先级 executor 完成后栈帧自然归还，<code>SP</code> 回退到被抢占 executor 的位置继续执行。每个 executor 本身就是一个常规 Rust 函数调用，其 <code>run()</code> 返回即栈帧销毁。</p><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to &quot;模块结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rt-async/</span></span>
<span class="line"><span>├── modules/</span></span>
<span class="line"><span>│   ├── executor/          # 核心调度器（Spawner/Executor/priority_bitmap/task）</span></span>
<span class="line"><span>│   ├── executor-macro/    # 过程宏（#[task]、#[main]、#[interrupt]）</span></span>
<span class="line"><span>│   ├── platform/          # 平台抽象 + driver model</span></span>
<span class="line"><span>│   │   ├── src/           #   device.rs（trait）driver.rs（registry）bus.rs dtb.rs irq.rs</span></span>
<span class="line"><span>│   │   │   └── drivers/   #     内置驱动（ns16550a/clint/sifive-plic/...）</span></span>
<span class="line"><span>│   │   ├── archs/         #   架构相关（riscv64-rt：中断使能/TrapFrame/idle/link.x）</span></span>
<span class="line"><span>│   │   └── chips/         #   板级实现（qemu-virt / std-chip）</span></span>
<span class="line"><span>│   ├── futures/           # async 原语（SerialRx/Timer/Mutex）</span></span>
<span class="line"><span>│   └── timer/             # 定时器队列</span></span>
<span class="line"><span>└── apps/</span></span>
<span class="line"><span>    ├── demo/              # 示例程序</span></span>
<span class="line"><span>    └── test/              # 集成测试（QEMU 运行）</span></span></code></pre></div><h2 id="调度模型" tabindex="-1">调度模型 <a class="header-anchor" href="#调度模型" aria-label="Permalink to &quot;调度模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>策略</th><th>机制</th></tr></thead><tbody><tr><td>跨优先级</td><td>抢占</td><td>高优先级 executor 抢占低优先级，通过 Pend ISR 在共享栈上嵌套运行</td></tr><tr><td>同优先级</td><td>协作</td><td>同 executor 内任务通过 <code>.await</code> 让权，FIFO 顺序执行</td></tr></tbody></table><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong><code>#![no_std]</code></strong> — 纯 Rust，无 libc 依赖，适合裸机部署</li><li><strong>任务数量无上限</strong> — 栈由 executor 调用链自然分配，不逐 task 分配栈</li><li><strong>零额外栈切换开销</strong> — executor 切换复用 Rust 函数调用/返回语义</li><li><strong>最多 4,096 个优先级</strong> — <code>PriorityBitmap&lt;G&gt;</code> 支持 G ∈ [1, 64]</li><li><strong>O(1) 就绪选择</strong> — 两级位图 <code>trailing_zeros()</code> 常数时间定位最高优先级</li></ul>`,15)])])}const x=s(p,[["render",r]]);export{h as __pageData,x as default};
